/* Display preferences never remove field values or change record calculations. */
function visibilityPrefs(){return db.displayPreferences||{columns:{},fields:{}}}
function saveVisibility(kind,key,value){let previous=db.displayPreferences;let prefs=structuredClone(visibilityPrefs());prefs.columns=prefs.columns||{};prefs.fields=prefs.fields||{};prefs[kind][key]=value;db.displayPreferences=prefs;if(save('Display preference saved')===false){db.displayPreferences=previous;return false}return true}
function columnProfile(table){return page+'|'+Array.from(table.tHead?.rows[0]?.cells||table.rows[0]?.cells||[]).map(c=>c.textContent.trim()).join('|')}
function applyColumnVisibility(table){let headers=Array.from(table.tHead?.rows[0]?.cells||table.rows[0]?.cells||[]),hidden=visibilityPrefs().columns?.[columnProfile(table)]||[];for(let row of table.rows)for(let i=0;i<row.cells.length;i++)row.cells[i].classList.toggle('userHiddenColumn',i>0&&headers[i]?.textContent.trim().toLowerCase()!=='actions'&&hidden.includes(i));table.dispatchEvent(new Event('resize'));window.dispatchEvent(new Event('resize'))}
function configureColumns(table){let headers=Array.from(table.tHead?.rows[0]?.cells||table.rows[0]?.cells||[]),profile=columnProfile(table),hidden=visibilityPrefs().columns?.[profile]||[];openModal('Show / Hide Columns',`<div class="formbody"><p>Choose columns to display. Hidden columns remain stored. The first column and Actions stay visible.</p><div class="visibilityChoices">${headers.map((h,i)=>{let label=h.textContent.trim()||'Column '+(i+1),locked=i===0||label.toLowerCase()==='actions';return `<label><input type="checkbox" data-visible-column="${i}" ${!hidden.includes(i)||locked?'checked':''} ${locked?'disabled':''}> ${esc(label)}${locked?' (required)':''}</label>`}).join('')}</div></div><div class="formactions"><button class="btn secondary" type="button" id="resetVisibleColumns">Show All</button>${btn('Close','cancel','secondary')}</div>`);for(let box of $$('#modalBody [data-visible-column]'))box.onchange=()=>{let next=$$('#modalBody [data-visible-column]').filter(b=>!b.checked&&!b.disabled).map(b=>Number(b.dataset.visibleColumn));if(saveVisibility('columns',profile,next))applyColumnVisibility(table);else box.checked=!box.checked};$('#resetVisibleColumns').onclick=()=>{if(saveVisibility('columns',profile,[])){for(let box of $$('#modalBody [data-visible-column]'))box.checked=true;applyColumnVisibility(table)}}}
function configureFormFields(key){let form=$('#billForm')||$('#recordForm');if(!form||form.querySelector('.fieldVisibilityPanel'))return;let body=form.querySelector('.formbody');if(!body)return;let candidates=Array.from(body.querySelectorAll('label.field')).map(label=>{let input=label.querySelector('[name]');return input?{label,input,name:input.name,title:label.querySelector('span')?.textContent.trim()||input.name}:null}).filter(Boolean);let optional=candidates.filter(c=>!c.input.required&&!c.input.readOnly&&c.name!=='id'&&c.input.type!=='hidden');if(!optional.length)return;let panel=document.createElement('details');panel.className='fieldVisibilityPanel';let hidden=visibilityPrefs().fields?.[key]||[];panel.innerHTML=`<summary>Show / Hide Fields</summary><p>Optional fields only. Hiding a field keeps its saved value.</p><div class="visibilityChoices">${optional.map(c=>`<label><input type="checkbox" data-visible-field="${esc(c.name)}" ${hidden.includes(c.name)?'':'checked'}> ${esc(c.title)}</label>`).join('')}</div><button type="button" class="btn secondary small" data-reset-fields>Show All Fields</button>`;body.before(panel);function apply(){let hidden=visibilityPrefs().fields?.[key]||[];for(let c of optional)c.label.classList.toggle('userHiddenField',hidden.includes(c.name))}for(let box of panel.querySelectorAll('[data-visible-field]'))box.onchange=()=>{let next=Array.from(panel.querySelectorAll('[data-visible-field]')).filter(b=>!b.checked).map(b=>b.dataset.visibleField);if(saveVisibility('fields',key,next))apply();else box.checked=!box.checked};panel.querySelector('[data-reset-fields]').onclick=()=>{if(saveVisibility('fields',key,[])){for(let box of panel.querySelectorAll('[data-visible-field]'))box.checked=true;apply()}};apply()}
const editBeforeVisibility=editRecord;
editRecord=function(key,id,initial){editBeforeVisibility(key,id,initial);if(!['jobs','sales','purchases'].includes(key))configureFormFields(key)};
const billBeforeVisibility=billForm;
billForm=function(key,id,initial){billBeforeVisibility(key,id,initial);configureFormFields(key)};
const renderBeforeVisibility=render;
render=function(){renderBeforeVisibility();for(let table of $$('#content table')){if(!table.rows.length)continue;applyColumnVisibility(table);let button=document.createElement('button');button.type='button';button.className='btn secondary small columnVisibilityButton';button.textContent='Show / Hide Columns';button.onclick=()=>configureColumns(table);let wrap=table.closest('.tablewrap')||table;wrap.before(button)}};
render();
